{"content": "#include "kernel_operator.h"

constexpr int BUFFER_NUM = 2;

struct TilingData {
    int64_t totalLength;
    int64_t formerNum;
    int64_t formerLength;
    int64_t tailNum;
    int64_t tailLength;
    int64_t tileLength;
    int64_t tileLengthAlign;
    int64_t dtypeSize;
    float alpha;
};

extern "C" __global__ __aicore__ void add_kernel(GM_ADDR x, GM_ADDR y, GM_ADDR out, GM_ADDR tiling) {
    TilingData tilingData;
    AscendC::CopyTiling(&tilingData, tiling);

    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::QuePosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::QuePosition::VECIN, BUFFER_NUM> inQueueY;
    AscendC::TQue<AscendC::QuePosition::VECOUT, BUFFER_NUM> outQueue;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> calcBuf;

    pipe.InitBuffer(inQueueX, BUFFER_NUM, tilingData.tileLengthAlign * tilingData.dtypeSize);
    pipe.InitBuffer(inQueueY, BUFFER_NUM, tilingData.tileLengthAlign * tilingData.dtypeSize);
    pipe.InitBuffer(outQueue, BUFFER_NUM, tilingData.tileLengthAlign * tilingData.dtypeSize);

    if (tilingData.dtypeSize == 2) {
        pipe.InitBuffer(calcBuf, tilingData.tileLengthAlign * sizeof(float));
    }

    AscendC::GlobalTensor<half> xGm;
    AscendC::GlobalTensor<half> yGm;
    AscendC::GlobalTensor<half> outGm;
    xGm.SetGlobalBuffer((__gm__ half*)x);
    yGm.SetGlobalBuffer((__gm__ half*)y);
    outGm.SetGlobalBuffer((__gm__ half*)out);

    int64_t blockIdx = GetBlockIdx();
    int64_t coreNum = tilingData.formerNum + tilingData.tailNum;
    int64_t loopCount = tilingData.tileLength;

    for (int64_t i = blockIdx; i < loopCount; i += coreNum) {
        int64_t offset = i * tilingData.tileLength;
        int64_t curLength = (i == loopCount - 1) ? tilingData.tailLength : tilingData.tileLength;

        AscendC::LocalTensor<half> xLocal = inQueueX.AllocTensor<half>();
        AscendC::LocalTensor<half> yLocal = inQueueY.AllocTensor<half>();
        AscendC::LocalTensor<half> outLocal = outQueue.AllocTensor<half>();

        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curLength * sizeof(half)), 0, 0, 0};
        AscendC::DataCopyPad(xLocal, xGm[offset], copyParams);
        AscendC::DataCopyPad(yLocal, yGm[offset], copyParams);

        inQueueX.EnQue(xLocal);
        inQueueY.EnQue(yLocal);

        xLocal = inQueueX.DeQue<half>();
        yLocal = inQueueY.DeQue<half>();

        if (tilingData.dtypeSize == 2) {
            AscendC::LocalTensor<float> xFp32 = calcBuf.Get<float>();
            AscendC::LocalTensor<float> yFp32 = calcBuf.Get<float>();
            AscendC::LocalTensor<float> outFp32 = calcBuf.Get<float>();

            AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curLength);
            AscendC::Cast(yFp32, yLocal, AscendC::RoundMode::CAST_NONE, curLength);

            AscendC::Muls(yFp32, yFp32, tilingData.alpha, curLength);
            AscendC::Add(outFp32, xFp32, yFp32, curLength);

            AscendC::Cast(outLocal, outFp32, AscendC::RoundMode::CAST_ROUND, curLength);
        } else {
            AscendC::Muls(outLocal, yLocal, tilingData.alpha, curLength);
            AscendC::Add(outLocal, xLocal, outLocal, curLength);
        }

        outQueue.EnQue(outLocal);
        outLocal = outQueue.DeQue<half>();

        AscendC::DataCopyPad(outGm[offset], outLocal, copyParams);

        inQueueX.FreeTensor(xLocal);
        inQueueY.FreeTensor(yLocal);
        outQueue.FreeTensor(outLocal);
    }
