{"content": "#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_add_kernel_fp32.h"
#include "aclrtlaunch_add_kernel_fp16.h"
#include "aclrtlaunch_add_kernel_bf16.h"

namespace ascend_kernel {

struct TilingData {
    int64_t totalLength;
    int64_t formerNum;
    int64_t formerLength;
    int64_t tailNum;
    int64_t tailLength;
    int64_t tileLength;
    int64_t tileLengthAlign;
    int64_t dtypeSize;
    float alpha;
};

at::Tensor add(const at::Tensor& x, const at::Tensor& y, double alpha) {
    // Input validation
    TORCH_CHECK(x.is_contiguous(), "Input x must be contiguous");
    TORCH_CHECK(y.is_contiguous(), "Input y must be contiguous");
    TORCH_CHECK(x.dtype() == y.dtype(), "Input tensors must have the same dtype");
    TORCH_CHECK(x.device().type() == at::DeviceType::PrivateUse1, "Input x must be on NPU");
    TORCH_CHECK(y.device().type() == at::DeviceType::PrivateUse1, "Input y must be on NPU");

    // Handle broadcasting: expand y to match x's shape
    auto y_broadcasted = y.broadcast_to(x.sizes());

    // Create output tensor
    auto output = at::empty_like(x);

    // Flatten for element-wise processing
    int64_t totalLength = x.numel();
    int64_t dtypeSize = x.element_size();

    // Get platform info
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // Block-level tiling: Cache Line 512B aligned
    int64_t totalLengthCoreAlign = ((totalLength * dtypeSize + 511) / 512) * 512 / dtypeSize;
    int64_t formerNum = totalLengthCoreAlign / coreNum;
    int64_t formerLength = coreNum;
    int64_t tailNum = totalLengthCoreAlign - formerNum * coreNum;
    int64_t tailLength = tailNum > 0 ? 1 : 0;

    if (tailNum > 0) {
        formerNum += 1;
        formerLength = coreNum;
        tailNum = totalLengthCoreAlign - formerNum * coreNum;
        tailLength = tailNum > 0 ? 1 : 0;
    }

    // UB-level tiling: 32B aligned
    int64_t bufferCoefficient = (dtypeSize == 4) ? 32 : 24;  // float32: 32, fp16/bf16: 24
    int64_t tileLength = (ubSize / bufferCoefficient) / dtypeSize;
    int64_t tileLengthAlign = ((tileLength * dtypeSize + 31) / 32) * 32 / dtypeSize;

    // Ensure tileLength doesn't exceed totalLength
    if (tileLength > totalLength) {
        tileLength = totalLength;
        tileLengthAlign = ((tileLength * dtypeSize + 31) / 32) * 32 / dtypeSize;
    }

    // Build tiling data
    TilingData tilingData;
    tilingData.totalLength = totalLength;
    tilingData.formerNum = formerNum;
    tilingData.formerLength = formerLength;
    tilingData.tailNum = tailNum;
    tilingData.tailLength = tailLength;
    tilingData.tileLength = tileLength;
    tilingData.tileLengthAlign = tileLengthAlign;
    tilingData.dtypeSize = dtypeSize;
    tilingData.alpha = static_cast<float>(alpha);

    // Flatten tensors for kernel
    auto x_flat = x.reshape({-1});
    auto y_flat = y_broadcasted.reshape({-1});
    auto out_flat = output.reshape({-1});

    int64_t blockDim = coreNum;
    float alpha_f = static_cast<float>(alpha);

    // Launch kernel based on dtype
    if (x.dtype() == at::kFloat) {
        EXEC_KERNEL_CMD(add_kernel_fp32, blockDim, x_flat, y_flat, out_flat, tilingData);
    } else if (x.dtype() == at::kHalf) {
        EXEC_KERNEL_CMD(add_kernel_fp16, blockDim, x_flat, y_flat, out_flat, tilingData);
    } else if (x.dtype() == at::kBFloat16) {
        EXEC_KERNEL_CMD(add_kernel_bf16, blockDim, x_flat, y_flat, out_flat, tilingData);
    } else {
        TORCH_CHECK(false, "Unsupported dtype for add_kernel: ", x.dtype());
    }

    return output;
}

} // namespace ascend_kernel
