    float alpha;
};

template <typename T>
class KernelAdd {
public:
    __aicore__ inline KernelAdd() {}
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR out, TilingData* tilingData) {
        tilingData_ = tilingData;
        xGm.SetGlobalBuffer((__gm__ T*)x);
        yGm.SetGlobalBuffer((__gm__ T*)y);
        outGm.SetGlobalBuffer((__gm__ T*)out);

        pipe.InitBuffer(inQueueX, BUFFER_NUM, tilingData_->tileLengthAlign * sizeof(T));
        pipe.InitBuffer(inQueueY, BUFFER_NUM, tilingData_->tileLengthAlign * sizeof(T));
        pipe.InitBuffer(outQueue, BUFFER_NUM, tilingData_->tileLengthAlign * sizeof(T));

        if constexpr (sizeof(T) == 2) {
            pipe.InitBuffer(calcBuf, tilingData_->tileLengthAlign * sizeof(float));
        }
    }

    __aicore__ inline void Process() {
        int64_t loopCount = tilingData_->formerNum + tilingData_->tailNum;
        int64_t coreNum = GetBlockNum();
        int64_t blockIdx = GetBlockIdx();

        for (int64_t i = blockIdx; i < loopCount; i += coreNum) {
            int64_t offset = i * tilingData_->tileLength;
            int64_t curLength = (i < tilingData_->formerNum) ? tilingData_->formerLength : tilingData_->tailLength;

            CopyIn(offset, curLength);
            Compute(curLength);
            CopyOut(offset, curLength);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t offset, int64_t curLength) {
        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        AscendC::LocalTensor<T> yLocal = inQueueY.AllocTensor<T>();

        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(xLocal, xGm[offset], copyParams);
        AscendC::DataCopyPad(yLocal, yGm[offset], copyParams);

        inQueueX.EnQue(xLocal);
        inQueueY.EnQue(yLocal);
    }

    __aicore__ inline void Compute(int64_t curLength) {
        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
        AscendC::LocalTensor<T> yLocal = inQueueY.DeQue<T>();
        AscendC::LocalTensor<T> outLocal = outQueue.AllocTensor<T>();

        if constexpr (sizeof(T) == 2) {
            AscendC::LocalTensor<float> xFp32 = calcBuf.Get<float>();
            AscendC::LocalTensor<float> yFp32 = calcBuf.Get<float>();
            AscendC::LocalTensor<float> outFp32 = calcBuf.Get<float>();

            AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curLength);
            AscendC::Cast(yFp32, yLocal, AscendC::RoundMode::CAST_NONE, curLength);

