            AscendC::Cast(outLocal, outFp32, AscendC::RoundMode::CAST_ROUND, curLength);
        } else {
            AscendC::Muls(outLocal, yLocal, tilingData_->alpha, curLength);
            AscendC::Add(outLocal, xLocal, outLocal, curLength);
        }

        outQueue.EnQue(outLocal);
        inQueueX.FreeTensor(xLocal);
        inQueueY.FreeTensor(yLocal);
    }

    __aicore__ inline void CopyOut(int64_t offset, int64_t curLength) {
        AscendC::LocalTensor<T> outLocal = outQueue.DeQue<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(outGm[offset], outLocal, copyParams);
        outQueue.FreeTensor(outLocal);
    }

