constexpr int BUFFER_NUM = 2;

template <typename T>
class KernelAdd {
public:
    __aicore__ inline KernelAdd() {}
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR out,
                                int64_t totalLength, int64_t tileLength, int64_t tileLengthAlign,
                                float alpha) {
        totalLength_ = totalLength;
        tileLength_ = tileLength;
        tileLengthAlign_ = tileLengthAlign;
        alpha_ = alpha;

        xGm.SetGlobalBuffer((__gm__ T*)x);
        yGm.SetGlobalBuffer((__gm__ T*)y);
        outGm.SetGlobalBuffer((__gm__ T*)out);

        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLengthAlign_ * sizeof(T));
        pipe.InitBuffer(inQueueY, BUFFER_NUM, tileLengthAlign_ * sizeof(T));
        pipe.InitBuffer(outQueue, BUFFER_NUM, tileLengthAlign_ * sizeof(T));

        if constexpr (sizeof(T) == 2) {
            pipe.InitBuffer(calcBuf, tileLengthAlign_ * sizeof(float));
        }
    }

    __aicore__ inline void Process() {
        int64_t loopCount = (totalLength_ + tileLength_ - 1) / tileLength_;
        int64_t coreNum = AscendC::GetBlockNum();
        int64_t blockIdx = AscendC::GetBlockIdx();

        for (int64_t i = blockIdx; i < loopCount; i += coreNum) {
            int64_t offset = i * tileLength_;
            int64_t curLength = (offset + tileLength_ <= totalLength_) ? tileLength_ : (totalLength_ - offset);

            CopyIn(offset, curLength);
            Compute(curLength);
            CopyOut(offset, curLength);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t offset, int64_t curLength) {
        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        AscendC::LocalTensor<T> yLocal = inQueueY.AllocTensor<T>();

        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
        AscendC::DataCopyPad(xLocal, xGm[offset], copyParams, padParams);
        AscendC::DataCopyPad(yLocal, yGm[offset], copyParams, padParams);

        inQueueX.EnQue(xLocal);
        inQueueY.EnQue(yLocal);
    }

    __aicore__ inline void Compute(int64_t curLength) {
        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
        AscendC::LocalTensor<T> yLocal = inQueueY.DeQue<T>();
        AscendC::LocalTensor<T> outLocal = outQueue.AllocTensor<T>();

        if constexpr (sizeof(T) == 2) {
            AscendC::LocalTensor<float> xFp32 = calcBuf.Get<float>();
            AscendC::LocalTensor<float> yFp32 = calcBuf.Get<float>();
            AscendC::LocalTensor<float> outFp32 = calcBuf.Get<float>();

            AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curLength);
            AscendC::Cast(yFp32, yLocal, AscendC::RoundMode::CAST_NONE, curLength);

            AscendC::Muls(yFp32, yFp32, alpha_, curLength);
            AscendC::Add(outFp32, xFp32, yFp32, curLength);

            AscendC::Cast(outLocal, outFp32, AscendC::RoundMode::CAST_ROUND, curLength);
        } else {
            AscendC::Muls(outLocal, yLocal, alpha_, curLength);
            AscendC::Add(outLocal, xLocal, outLocal, curLength);
        }

        outQueue.EnQue(outLocal);
        inQueueX.FreeTensor(xLocal);
        inQueueY.FreeTensor(yLocal);
    }

    __aicore__ inline void CopyOut(int64_t offset, int64_t curLength) {
        AscendC::LocalTensor<T> outLocal = outQueue.DeQue<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(outGm[offset], outLocal, copyParams);
        outQueue.FreeTensor(outLocal);
    }

private:
    int64_t totalLength_ = 0;
    int64_t tileLength_ = 0;
    int64_t tileLengthAlign_ = 0;
    float alpha_ = 1.0f;

    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::QuePosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::QuePosition::VECIN, BUFFER_NUM> inQueueY;
    AscendC::TQue<AscendC::QuePosition::VECOUT, BUFFER_NUM> outQueue;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> calcBuf;
    AscendC::GlobalTensor<T> xGm;
    AscendC::GlobalTensor<T> yGm;
    AscendC::GlobalTensor<T> outGm;
};

