    int64_t totalLength, int64_t tileLength, int64_t tileLengthAlign, float alpha) {
    KernelAdd<float> op;
    op.Init(x, y, out, totalLength, tileLength, tileLengthAlign, alpha);
    op.Process();
}

extern "C" __global__ __aicore__ void add_kernel_fp16(GM_ADDR x, GM_ADDR y, GM_ADDR out,
    int64_t totalLength, int64_t tileLength, int64_t tileLengthAlign, float alpha) {
    KernelAdd<half> op;
