13	at::Tensor add(const at::Tensor& x, const at::Tensor& y, double alpha) {
14	    // Input validation
15	    TORCH_CHECK(x.is_contiguous(), "Input x must be contiguous");
16	    TORCH_CHECK(y.is_contiguous(), "Input y must be contiguous");
17	    TORCH_CHECK(x.dtype() == y.dtype(), "Input tensors must have the same dtype");
18	    TORCH_CHECK(x.device().type() == at::DeviceType::PrivateUse1, "Input x must be on NPU");
19	    TORCH_CHECK(y.device().type() == at::DeviceType::PrivateUse1, "Input y must be on NPU");
20	
21	    // Handle broadcasting: expand y to match x's shape
22	    auto y_broadcasted = y.broadcast_to(x.sizes());
23	
24	    // Create output tensor
25	    auto output = at::empty_like(x);
26	
27	    // Flatten for element-wise processing
28	    int64_t totalLength = x.numel();
29	    int64_t dtypeSize = x.element_size();
30	
31	    // Get platform info
32	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
33	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
34	    uint64_t ubSize;
35	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
36	
37	    // UB-level tiling: 32B aligned
38	    int64_t bufferCoefficient = (dtypeSize == 4) ? 32 : 24;  // float32: 32, fp16/bf16: 24
39	    int64_t tileLength = (ubSize / bufferCoefficient) / dtypeSize;
40	    int64_t tileLengthAlign = ((tileLength * dtypeSize + 31) / 32) * 32 / dtypeSize;
41	
42	    // Ensure tileLength doesn't exceed totalLength
43	    if (tileLength > totalLength) {
44	        tileLength = totalLength;
45	        tileLengthAlign = ((tileLength * dtypeSize + 31) / 32) * 32 / dtypeSize;
46	    }
47	
48	    // Flatten tensors for kernel
49	    auto x_flat = x.reshape({-1});
50	    auto y_flat = y_broadcasted.reshape({-1});
51	    auto out_flat = output.reshape({-1});
52	
53	    int64_t blockDim = coreNum;
54	    float alpha_f = static_cast<float>(alpha);
55	
56	    // Launch kernel based on dtype
57	    if (x.dtype() == at::kFloat) {
58	        EXEC_KERNEL_CMD(add_kernel_fp32, blockDim, x_flat, y_flat, out_flat,
59	                        totalLength, tileLength, tileLengthAlign, alpha_f);
60	    } else if (x.dtype() == at::kHalf) {
61	        EXEC_KERNEL_CMD(add_kernel_fp16, blockDim, x_flat, y_flat, out_flat,
62	                        totalLength, tileLength, tileLengthAlign, alpha_f);
63	    } else if (x.dtype() == at::kBFloat16) {
64	        EXEC_KERNEL_CMD(add_kernel_bf16, blockDim, x_flat, y_flat, out_flat,
65	                        totalLength, tileLength, tileLengthAlign, alpha_f);
66	    } else {
67	        TORCH_CHECK(false, "Unsupported dtype for add_kernel: ", x.dtype());
68	    }
69	
70	    return output;
71	}
