32	        int64_t loopCount = (totalLength_ + tileLength_ - 1) / tileLength_;
33	        int64_t coreNum = AscendC::GetBlockNum();
34	        int64_t blockIdx = AscendC::GetBlockIdx();
35	
36	        for (int64_t i = blockIdx; i < loopCount; i += coreNum) {
37	            int64_t offset = i * tileLength_;
38	            int64_t curLength = (offset + tileLength_ <= totalLength_) ? tileLength_ : (totalLength_ - offset);
39	
40	            CopyIn(offset, curLength);
41	            Compute(curLength);
42	            CopyOut(offset, curLength);
43	        }
44	    }
