48	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
49	        AscendC::LocalTensor<T> yLocal = inQueueY.AllocTensor<T>();
50	
51	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curLength * sizeof(T)), 0, 0, 0};
52	        AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
53	        AscendC::DataCopyPad(xLocal, xGm[offset], copyParams, padParams);
54	        AscendC::DataCopyPad(yLocal, yGm[offset], copyParams, padParams);
