61	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
62	        AscendC::LocalTensor<T> yLocal = inQueueY.DeQue<T>();
63	        AscendC::LocalTensor<T> outLocal = outQueue.AllocTensor<T>();
